def combined_notes_to_all(apps, schema_editor):
    """A combined (cross-exam) topic note is filed under the new exam_type 'all'."""
    TopicNote = apps.get_model('questions', 'TopicNote')
    TopicNote.objects.filter(is_combined=True).update(exam_type='all')


def backfill_attempt_log(apps, schema_editor):
    """One 'backfill' log row per existing QuestionAttempt (QuestionAttempt keeps only the latest pick,
    so is_first=True is an approximation, documented in docs/audit/MEDICAL_ACCURACY_DESIGN.md)."""
    QuestionAttempt = apps.get_model('questions', 'QuestionAttempt')
    QuestionAttemptLog = apps.get_model('questions', 'QuestionAttemptLog')
    batch = []
    for attempt in QuestionAttempt.objects.order_by('id').iterator(chunk_size=1000):
        batch.append(QuestionAttemptLog(
            user_id=attempt.user_id, question_id=attempt.question_id,
            selected_answer=(attempt.selected_answer or '')[:1], is_correct=attempt.is_correct,
            source='backfill', is_first=True, created_at=attempt.attempted_at,
        ))
        if len(batch) >= 1000:
            QuestionAttemptLog.objects.bulk_create(batch)
            batch = []
    if batch:
        QuestionAttemptLog.objects.bulk_create(batch)


def remove_backfill(apps, schema_editor):
    apps.get_model('questions', 'QuestionAttemptLog').objects.filter(source='backfill').delete()


